// =============================================================================================================================================
// orbitals -- the "orbitals" data format, version 2: what a program writes for Shaders/fields/orbitals.glsl and levels.glsl to draw. Every
// value a float in the file (counts and indices whole numbers, exact to 2^24).
//   header     17  version 2, header length (17), atoms A, shells S, primitives P, functions N, orbitals M, total energy, atom stride (4),
//                  shell stride (4), primitive stride (2), orbital stride (4 + N), function kind (0 Gaussian, 1 Slater), electrons, occupied
//                  (restricted: pairs; unrestricted: alpha electrons), spin (0 restricted, 1 unrestricted), the density's size (one atom:
//                  the bohr holding 90% of the electrons; 0 otherwise)
//   atoms      A x 4   x, y, z (bohr), Z
//   shells     S x 4   atom, l, first primitive, primitive count
//   primitives P x 2   exponent, coefficient (on the normalized primitive, contraction included)
//   orbitals   M x (4 + N)  occupation, energy (hartree), N coefficients, the orbital's peak |psi|, its size (one atom: the bohr holding 90%
//                  of it; 0 otherwise) -- unrestricted: M alpha rows, then M beta rows
// Function kind 0: primitive norm (2a/pi)^(3/4) (4a)^(l/2) exp(-a r^2); kind 1 (Slater): N_l exp(-zeta r), N_l = sqrt((2l+1)!! (2 zeta)^(2l+3) /
// (4 pi (2l+2)!)); each Cartesian component carries 1 / sqrt((2a-1)!! (2b-1)!! (2c-1)!!).
//
// A library: it declares the file's buffer (orbitals), the peaks' working buffers, and three kernels. The program sets five symbols --
// orbitals_atoms, orbitals_shells, orbitals_primitives, orbitals_functions, orbitals_rows (M, or 2M unrestricted) -- fills the buffer with
// its own kernel (Ir77OrbitalsHeader, then the sections, then a row each), runs OrbitalsSample, OrbitalsPeaks, OrbitalsSpread (each row's
// peak and size, the density's size), and writes it: write <name> orbitals 2 orbitals ...
// The peaks sample rays out of every atom -- 128 radii (0.01 to 80 bohr, geometric) along 146 directions (a Fibonacci sphere) -- from the
// values as the file will hold them (floats), so the reader shows an orbital relative to its own peak.
// =============================================================================================================================================

// @symbol int orbitals_atoms orbitals_shells orbitals_primitives orbitals_functions orbitals_rows
// @buffer orbitals 17+4*orbitals_atoms+4*orbitals_shells+2*orbitals_primitives+orbitals_rows*(4+orbitals_functions)
// @buffer orbitals_samples 2 128*orbitals_atoms orbitals_rows
// @buffer orbitals_density 128
// @kernel OrbitalsSample 4*orbitals_atoms*(orbitals_rows+31)
// @kernel OrbitalsPeaks orbitals_rows
// @kernel OrbitalsSpread 1

#define IR77_ORBITALS_VERSION 2
#define IR77_ORBITALS_HEADER 17
#define IR77_ORBITALS_RADII 128
#define IR77_ORBITALS_DIRECTIONS 146
#define IR77_ORBITALS_REACH 80.0
#define IR77_ORBITALS_HOLDS 0.9
#define IR77_ORBITALS_PI 3.14159265358979323846

// ---- writing -------------------------------------------------------------------------------------------------------------------------------

void Ir77OrbitalsHeader(__global double* out, int atoms, int shells, int primitives, int functions, int orbitals, double energy, int kind,
                        int electrons, int occupied, int unrestricted) {
    double header[IR77_ORBITALS_HEADER] = {IR77_ORBITALS_VERSION, IR77_ORBITALS_HEADER, atoms, shells, primitives, functions, orbitals, energy, 4, 4,
                                           2, 4 + functions, kind, electrons, occupied, unrestricted, 0};
    for (int k = 0; k < IR77_ORBITALS_HEADER; k++) out[k] = header[k];
}

int Ir77OrbitalsWhole(double v) { return (int)(fmax((float)v, 0.0f) + 0.5f); }

__global double* Ir77OrbitalsAtoms(__global double* out) { return out + Ir77OrbitalsWhole(out[1]); }

__global double* Ir77OrbitalsShells(__global double* out) { return Ir77OrbitalsAtoms(out) + Ir77OrbitalsWhole(out[2]) * 4; }

__global double* Ir77OrbitalsPrimitives(__global double* out) { return Ir77OrbitalsShells(out) + Ir77OrbitalsWhole(out[3]) * 4; }

// a row -- occupation, energy, then its coefficients
__global double* Ir77OrbitalsRow(__global double* out, int row) {
    return Ir77OrbitalsPrimitives(out) + Ir77OrbitalsWhole(out[4]) * 2 + (long)row * Ir77OrbitalsWhole(out[11]);
}

// the header's counts, then the atoms, shells and primitives copied in -- a Gaussian basis as the basis library builds it
void Ir77OrbitalsBasis(__global double* out, int atoms, int shells, int primitives, int functions, int orbitals, double energy, int kind,
                       int electrons, int occupied, int unrestricted, __global const double* centres, __global const double* shell_table,
                       __global const double* shell_primitives) {
    Ir77OrbitalsHeader(out, atoms, shells, primitives, functions, orbitals, energy, kind, electrons, occupied, unrestricted);
    __global double* a = Ir77OrbitalsAtoms(out);
    for (int k = 0; k < 4 * atoms; k++) a[k] = centres[k];
    __global double* s = Ir77OrbitalsShells(out);
    for (int k = 0; k < 4 * shells; k++) s[k] = shell_table[k];
    __global double* p = Ir77OrbitalsPrimitives(out);
    for (int k = 0; k < 2 * primitives; k++) p[k] = shell_primitives[k];
}

// ---- the peaks -----------------------------------------------------------------------------------------------------------------------------

double Ir77OrbitalsRadius(int ri) { return 0.01 * pow(IR77_ORBITALS_REACH / 0.01, ri / (IR77_ORBITALS_RADII - 1.0)); }

// n!!
double Ir77OrbitalsDoubleFactorial(int n) {
    double r = 1.0;
    for (int i = n; i > 1; i -= 2) r *= i;
    return r;
}

// the primitive's normalization as the reader applies it
double Ir77OrbitalsNorm(double alpha, int l, int slater) {
    if (!slater) return pow(2.0 * alpha / IR77_ORBITALS_PI, 0.75) * pow(4.0 * alpha, 0.5 * (double)l);
    double fact = 1.0;
    for (int i = 2; i <= 2 * l + 2; i++) fact *= (double)i;
    return sqrt(Ir77OrbitalsDoubleFactorial(2 * l + 1) * pow(2.0 * alpha, (double)(2 * l + 3)) / (4.0 * IR77_ORBITALS_PI * fact));
}

// a value as the file holds it
double Ir77OrbitalsFloat(double v) { return (double)(float)v; }

// A block of rows on one ray-shell -- (rows from 32 b, atom, radius) s.i: each orbital at that radius from that atom along every direction
// -> orbitals_samples[row]: the largest |psi| there, and the mean of psi^2 over the directions. A few directions at a time, shell by shell:
// each primitive's normalization once, each basis function's value once for the whole block of rows.
#define IR77_ORBITALS_ROW_BLOCK 32         // rows an item -- the kernel's size 128 atoms ceil(rows / 32), written 4 atoms (rows + 31)
#define IR77_ORBITALS_DIRECTION_BLOCK 16   // directions at a time
#define IR77_ORBITALS_SHELL_PRIMITIVES 16  // a shell's primitives -- past it, the rest are left out (l up to 3: f)

void OrbitalsSample(Ir77Stage s) {
    __global double* out = s.orbitals;
    int atoms = Ir77OrbitalsWhole(out[2]), shells = Ir77OrbitalsWhole(out[3]), functions = Ir77OrbitalsWhole(out[5]);
    int orbitals = Ir77OrbitalsWhole(out[6]), rows = orbitals * (Ir77OrbitalsWhole(out[15]) ? 2 : 1);
    int slater = Ir77OrbitalsWhole(out[12]) == 1;
    __global double* atom_at = Ir77OrbitalsAtoms(out);
    __global double* shell_at = Ir77OrbitalsShells(out);
    __global double* primitive_at = Ir77OrbitalsPrimitives(out);

    int ri = s.i % IR77_ORBITALS_RADII, a = (s.i / IR77_ORBITALS_RADII) % atoms, block = s.i / (IR77_ORBITALS_RADII * atoms);
    int first_row = block * IR77_ORBITALS_ROW_BLOCK;
    if (first_row >= rows) return;
    int block_rows = min(IR77_ORBITALS_ROW_BLOCK, rows - first_row);
    double radius = Ir77OrbitalsRadius(ri);
    __global double* coefficients = Ir77OrbitalsRow(out, first_row) + 2;  // row r's at coefficients + r stride
    int stride = Ir77OrbitalsWhole(out[11]);

    double peak[IR77_ORBITALS_ROW_BLOCK], mean[IR77_ORBITALS_ROW_BLOCK];
    for (int r = 0; r < block_rows; r++) peak[r] = mean[r] = 0.0;

    for (int d0 = 0; d0 < IR77_ORBITALS_DIRECTIONS; d0 += IR77_ORBITALS_DIRECTION_BLOCK) {
        int directions = min(IR77_ORBITALS_DIRECTION_BLOCK, IR77_ORBITALS_DIRECTIONS - d0);

        // these sample points -- a Fibonacci sphere of this radius about the atom
        double px[IR77_ORBITALS_DIRECTION_BLOCK], py[IR77_ORBITALS_DIRECTION_BLOCK], pz[IR77_ORBITALS_DIRECTION_BLOCK];
        double psi[IR77_ORBITALS_ROW_BLOCK][IR77_ORBITALS_DIRECTION_BLOCK];
        for (int d = 0; d < directions; d++) {
            int direction = d0 + d;
            double dz = 1.0 - 2.0 * (direction + 0.5) / IR77_ORBITALS_DIRECTIONS;
            double dr = sqrt(fmax(1.0 - dz * dz, 0.0));
            double angle = direction * 2.39996322972865332;
            px[d] = Ir77OrbitalsFloat(atom_at[4 * a]) + radius * dr * cos(angle);
            py[d] = Ir77OrbitalsFloat(atom_at[4 * a + 1]) + radius * dr * sin(angle);
            pz[d] = Ir77OrbitalsFloat(atom_at[4 * a + 2]) + radius * dz;
            for (int r = 0; r < block_rows; r++) psi[r][d] = 0.0;
        }

        int mu = 0;
        for (int k = 0; k < shells; k++) {
            int atom = Ir77OrbitalsWhole(shell_at[4 * k]), l = Ir77OrbitalsWhole(shell_at[4 * k + 1]), first = Ir77OrbitalsWhole(shell_at[4 * k + 2]),
                count = min(Ir77OrbitalsWhole(shell_at[4 * k + 3]), IR77_ORBITALS_SHELL_PRIMITIVES);
            double cx = Ir77OrbitalsFloat(atom_at[4 * atom]), cy = Ir77OrbitalsFloat(atom_at[4 * atom + 1]), cz = Ir77OrbitalsFloat(atom_at[4 * atom + 2]);

            double alpha[IR77_ORBITALS_SHELL_PRIMITIVES], weight[IR77_ORBITALS_SHELL_PRIMITIVES];
            for (int p = 0; p < count; p++) {
                alpha[p] = Ir77OrbitalsFloat(primitive_at[2 * (first + p)]);
                weight[p] = Ir77OrbitalsFloat(primitive_at[2 * (first + p) + 1]) * Ir77OrbitalsNorm(alpha[p], l, slater);
            }

            // the components -- a from l down, then b: each its normalization
            int pa[10], pb[10], pc[10];
            double norm[10];
            int components = 0;
            for (int x = l; x >= 0; x--)
                for (int y = l - x; y >= 0; y--) {
                    pa[components] = x, pb[components] = y, pc[components] = l - x - y;
                    norm[components] = 1.0 / sqrt(Ir77OrbitalsDoubleFactorial(2 * x - 1) * Ir77OrbitalsDoubleFactorial(2 * y - 1) *
                                                  Ir77OrbitalsDoubleFactorial(2 * (l - x - y) - 1));
                    components++;
                }

            // this shell's coefficients for the block's rows, as the file holds them
            double cf[10][IR77_ORBITALS_ROW_BLOCK];
            for (int q = 0; q < components; q++)
                for (int r = 0; r < block_rows; r++) cf[q][r] = mu + q < functions ? Ir77OrbitalsFloat(coefficients[(long)r * stride + mu + q]) : 0.0;

            for (int d = 0; d < directions; d++) {
                double x = px[d] - cx, y = py[d] - cy, z = pz[d] - cz;
                double r2 = x * x + y * y + z * z;
                double r = slater ? sqrt(r2) : r2;  // what the exponent multiplies
                double radial = 0.0;
                for (int p = 0; p < count; p++) radial += weight[p] * exp(-alpha[p] * r);
                // x^0 .. x^l, likewise y and z
                double xp[4] = {1.0, x, x * x, x * x * x}, yp[4] = {1.0, y, y * y, y * y * y}, zp[4] = {1.0, z, z * z, z * z * z};
                for (int q = 0; q < components; q++) {
                    double phi = radial * xp[pa[q]] * yp[pb[q]] * zp[pc[q]] * norm[q];
                    for (int r = 0; r < block_rows; r++) psi[r][d] += cf[q][r] * phi;
                }
            }
            mu += components;
        }

        for (int r = 0; r < block_rows; r++)
            for (int d = 0; d < directions; d++) {
                peak[r] = fmax(peak[r], fabs(psi[r][d]));
                mean[r] += psi[r][d] * psi[r][d] / IR77_ORBITALS_DIRECTIONS;
            }
    }

    for (int r = 0; r < block_rows; r++) {
        long at = 2L * (((long)(first_row + r) * atoms + a) * IR77_ORBITALS_RADII + ri);
        s.orbitals_samples[at] = peak[r];
        s.orbitals_samples[at + 1] = mean[r];
    }
}

// the radius holding HOLDS of a radial mean's probability -- cumulative 4 pi r^2 <psi^2> over the radii (mean[ri * stride])
double Ir77OrbitalsSize(__global const double* mean, int stride) {
    double cumulative[IR77_ORBITALS_RADII];
    cumulative[0] = 0.0;
    for (int ri = 1; ri < IR77_ORBITALS_RADII; ri++) {
        double r0 = Ir77OrbitalsRadius(ri - 1), r1 = Ir77OrbitalsRadius(ri);
        cumulative[ri] = cumulative[ri - 1] + 0.5 * (r1 - r0) * (r0 * r0 * mean[(ri - 1) * stride] + r1 * r1 * mean[ri * stride]);
    }
    double whole = cumulative[IR77_ORBITALS_RADII - 1];
    if (whole <= 0.0) return 0.0;
    for (int ri = 1; ri < IR77_ORBITALS_RADII; ri++)
        if (cumulative[ri] >= IR77_ORBITALS_HOLDS * whole) {
            double t = (IR77_ORBITALS_HOLDS * whole - cumulative[ri - 1]) / fmax(cumulative[ri] - cumulative[ri - 1], 1e-300);
            return Ir77OrbitalsRadius(ri - 1) + t * (Ir77OrbitalsRadius(ri) - Ir77OrbitalsRadius(ri - 1));
        }
    return IR77_ORBITALS_REACH;
}

// row s.i's peak |psi| over every sample, and (one atom) its size
void OrbitalsPeaks(Ir77Stage s) {
    __global double* out = s.orbitals;
    int atoms = Ir77OrbitalsWhole(out[2]), functions = Ir77OrbitalsWhole(out[5]);
    int row = s.i;
    __global double* samples = s.orbitals_samples + 2L * IR77_ORBITALS_RADII * atoms * row;
    double peak = 0.0;
    for (int k = 0; k < IR77_ORBITALS_RADII * atoms; k++) peak = fmax(peak, samples[2 * k]);
    __global double* r = Ir77OrbitalsRow(out, row);
    r[2 + functions] = peak;
    r[3 + functions] = atoms == 1 ? Ir77OrbitalsSize(samples + 1, 2) : 0.0;
}

// the density's size (one atom) -- the rows' means weighted by their occupations -> header[16]
void OrbitalsSpread(Ir77Stage s) {
    __global double* out = s.orbitals;
    int atoms = Ir77OrbitalsWhole(out[2]), orbitals = Ir77OrbitalsWhole(out[6]), unrestricted = Ir77OrbitalsWhole(out[15]);
    int rows = orbitals * (unrestricted ? 2 : 1);
    out[16] = 0.0;
    if (atoms != 1) return;
    for (int ri = 0; ri < IR77_ORBITALS_RADII; ri++) {
        double sum = 0.0;
        for (int row = 0; row < rows; row++) sum += Ir77OrbitalsFloat(Ir77OrbitalsRow(out, row)[0]) * s.orbitals_samples[2 * (row * IR77_ORBITALS_RADII + ri) + 1];
        s.orbitals_density[ri] = sum;
    }
    out[16] = Ir77OrbitalsSize(s.orbitals_density, 1);
}
